def upgrade() -> None:
    conn = op.get_bind()
    stmt = sa.text(
        "UPDATE words SET"
        "  abstract_example_en = COALESCE(abstract_example_en, :hint_en),"
        "  abstract_example_ru = COALESCE(abstract_example_ru, :hint_ru) "
        "WHERE track = 'en' AND normalized_word = :n"
    )
    for n, hint_en, hint_ru in HINTS:
        conn.execute(stmt, {"n": n, "hint_en": hint_en, "hint_ru": hint_ru})


def downgrade() -> None:
    conn = op.get_bind()
    stmt = sa.text(
        "UPDATE words SET abstract_example_en = NULL, abstract_example_ru = NULL "
        "WHERE track = 'en' AND normalized_word = :n AND abstract_example_en = :hint_en"
    )
    for n, hint_en, _hint_ru in HINTS:
        conn.execute(stmt, {"n": n, "hint_en": hint_en})
